import { Request, Response } from 'express';
import { GetProductStockUseCase } from '../application/GetProductStockUseCase';

export class ProductController {
  constructor(private getProductStockUseCase: GetProductStockUseCase) {}

  getStock = (req: Request, res: Response): void => {
    try {
      const productId = Array.isArray(req.params.productId) ? req.params.productId[0] : req.params.productId;
      const response = this.getProductStockUseCase.execute(productId);
      res.json(response);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(404).json({ error: message });
    }
  };

  getAllStock = (req: Request, res: Response): void => {
    try {
      const response = this.getProductStockUseCase.executeAll();
      res.json({ products: response });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  };
}

